const r = $('POST /score').first().json;
const tgt = r.meta.target_day;
const preds = r.predictions.filter(p=>String(p.dt_local).slice(0,10)===tgt);
const nDA = preds.filter(p=>p.decision==='BUY_DA').length;
const nNEU = preds.filter(p=>p.decision==='NEUTRAL_5050').length;
const nRT = preds.filter(p=>p.decision==='BUY_RT').length;
const maxSpike = preds.length ? Math.max(...preds.map(p=>p.p_spike)) : 0;
const bf = (r.meta.backfilled_days||[]).join(',');
const det = (r.model_detail||[]).filter(d=>String(d.dt_local).slice(0,10)===tgt);
const lowAgree = det.filter(d=>d.agree_n<=3).length;
const avgStd = det.length ? +(det.reduce((a,d)=>a+d.e_dart_std,0)/det.length).toFixed(2) : null;
const maxStd = det.length ? Math.max(...det.map(d=>d.e_dart_std)) : null;
const compact = preds.map(p=>({h:new Date(p.dt_local).getHours(), pDA:p.p_da_cheap, pRT:p.p_rt_cheap, pSpk:p.p_spike, eD:p.e_dart, d:p.decision==='BUY_DA'?'DA':(p.decision==='BUY_RT'?'RT':'N')}));
return [{json:{target_day:tgt, nDA, nNEU, nRT, maxSpike, backfilled:bf, lowAgree, avgStd, maxStd, compact:JSON.stringify(compact)}}];

// batchGet 결과 파싱: 0=state전체, 1=predictions dt_local, 2=actuals dt_local, 3~8=탭 헤더
const vr = ($input.first().json.valueRanges) || [];
const rows = i => ((vr[i] || {}).values) || [];

function toObjects(vals) {
  if (!vals.length) return [];
  const hdr = vals[0].map(h => String(h).trim());
  return vals.slice(1).map(r => {
    const o = {};
    hdr.forEach((h, j) => { o[h] = (r[j] === undefined || r[j] === '') ? null : r[j]; });
    return o;
  });
}

// 시트는 dt_local을 날짜값으로 저장해 '2026-07-25 0:00:00'(0패딩 없음)으로 돌려준다.
// 코드는 '00:00:00'을 쓰므로 반드시 정규화해야 비교가 성립한다.
function norm(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') {                       // 구글 시리얼 날짜
    const ms = Math.round((v - 25569) * 86400000);
    return new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
  }
  const s = String(v).trim().replace('T', ' ');
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ ]?(\d{1,2})?:?(\d{1,2})?:?(\d{1,2})?/);
  if (!m) return s;
  const p = (x, n2) => String(x || 0).padStart(n2, '0');
  return `${m[1]}-${p(m[2],2)}-${p(m[3],2)} ${p(m[4],2)}:${p(m[5],2)}:${p(m[6],2)}`;
}

const state = toObjects(rows(0)).filter(r => r.dt_local).slice(-720);
if (state.length < 192) {
  throw new Error(`state 행 부족: ${state.length} (192 이상 필요). state 탭/헤더 확인`);
}
const col = i => rows(i).slice(1).map(r => norm(r[0])).filter(Boolean);
const predDays  = [...new Set(col(1).map(s => s.slice(0, 10)))];
const actHours  = [...new Set(col(2))].slice(-2000);

const wm = $('Fetch Open-Meteo').first().json;
let wp = null;
try { const p = $('Fetch Open-Meteo prev').first().json; wp = (p && p.hourly) ? p.hourly : null; } catch (e) {}

return [{ json: {
  state, weather: wm.hourly || null, weather_prev: wp,
  have_pred_days: predDays, have_actual_hours: actHours, max_backfill_days: 7,
  _n: { state: state.length, predDays: predDays.length, actHours: actHours.length }
} }];

const TABS = ["predictions","model_detail","state","actuals","daily_summary","runlog"];
const vr = $('Read sheets (1 call)').first().json.valueRanges || [];
const H = {};
TABS.forEach((t, i) => { H[t] = (((vr[i + 3] || {}).values) || [[]])[0] || []; });

// 시트는 dt_local을 날짜값으로 저장해 '2026-07-25 0:00:00'(0패딩 없음)으로 돌려준다.
// 코드는 '00:00:00'을 쓰므로 반드시 정규화해야 비교가 성립한다.
function norm(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') {                       // 구글 시리얼 날짜
    const ms = Math.round((v - 25569) * 86400000);
    return new Date(ms).toISOString().slice(0, 19).replace('T', ' ');
  }
  const s = String(v).trim().replace('T', ' ');
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ ]?(\d{1,2})?:?(\d{1,2})?:?(\d{1,2})?/);
  if (!m) return s;
  const p = (x, n2) => String(x || 0).padStart(n2, '0');
  return `${m[1]}-${p(m[2],2)}-${p(m[3],2)} ${p(m[4],2)}:${p(m[5],2)}:${p(m[6],2)}`;
}

const colSet = i => new Set(((((vr[i] || {}).values) || []).slice(1)).map(r => norm(r[0])).filter(Boolean));
const havePredTs = colSet(1);      // predictions!A:A
const haveMdTs   = colSet(9);      // model_detail!A:A

const r = $('POST /score').first().json;
const m = r.meta, gen = m.generated_at;

// 이미 시트에 있는 시각은 제외 — 재실행해도 중복 append 되지 않음
const preds = (r.predictions || []).filter(o => !havePredTs.has(norm(o.dt_local)));
const mdet  = (r.model_detail || []).filter(o => !haveMdTs.has(norm(o.dt_local)));

const rows = {};
rows.predictions  = preds.map(o => ({ ...o, generated_at: gen }));
rows.model_detail = mdet.map(o => ({ ...o, generated_at: gen }));
rows.state        = (r.new_state   || []);
rows.actuals      = (r.settlements || []);

// daily_summary — 시트의 기존 9컬럼 스키마에 맞춤
let summary = [];
try {
  const c = $('Prep Claude input').first().json;
  const resp = $('Claude 일일 요약').first().json;
  let txt = (resp.content && resp.content[0] && resp.content[0].text) ? resp.content[0].text : '';
  let j = {};
  try { j = JSON.parse(txt.replace(/^```(json)?/i, '').replace(/```$/, '').trim()); }
  catch (e) { j = { model_3class_summary: txt.slice(0, 900), spike_model_summary: '', final_recommendation: '' }; }
  summary = [{
    run_date: String(gen).slice(0, 10),
    target_day: c.target_day,
    n_buy_da: c.nDA, n_neutral: c.nNEU, n_buy_rt: c.nRT,
    max_p_spike: c.maxSpike,
    model_3class_summary: j.model_3class_summary || '',
    spike_model_summary: j.spike_model_summary || '',
    final_recommendation: j.final_recommendation || ''
  }];
} catch (e) {}
rows.daily_summary = summary;

rows.runlog = [{
  run_at: gen, target_day: m.target_day,
  todo_days: (m.todo_days || []).join(','),
  processed: (m.processed_days || []).map(p => `${p.day}:${p.source}${p.state_written ? '+state' : ''}`).join(' ; '),
  skipped:   (m.skipped_days || []).map(s => `${s.day}:${s.reason}`).join(' ; '),
  backfilled: (m.backfilled_days || []).join(','),
  state_rows_returned: m.n_state_rows_returned,
  state_days_in_sheet: (m.state_days_in_sheet || []).join(','),
  model_detail_rows: m.n_model_detail_rows,
  n_settlements: m.n_settlements ?? '',
  settlement_notes: ((m.settlement_diag || {}).notes || []).join(' ; '),
  eia_ok: (m.eia || {}).ok === true ? `ok(${(m.eia||{}).rows}행, ~${(m.eia||{}).last||''})`
        : `실패(key_set=${(m.eia||{}).key_set})`,
  feature_health: (() => { const fh = m.feature_health || {};
    const bad = Object.keys(fh.high_nan || {}); const miss = fh.missing || [];
    return (bad.length || miss.length) ? `결측>50%: ${bad.join(',')} / 누락: ${miss.join(',')}` : 'ok'; })()
}];

const out = [];
for (const t of TABS) {
  const data = rows[t] || [];
  if (!data.length) continue;
  const hdr = H[t];
  if (!hdr.length) continue;
  const values = data.map(o => hdr.map(h => {
    const v = o[String(h).trim()];
    return (v === undefined || v === null || (typeof v === 'number' && !isFinite(v))) ? '' : v;
  }));
  out.push({ json: { tab: t, values, n: values.length } });
}
return out.length ? out : [{ json: { tab: 'runlog', values: [], n: 0 } }];
